        World world=EncounterScenarios.CourierFulfillmentTest();int id;Require(world.TrySpawn(Species.Human,2,5,out id),"Could not add second courier.");SaveDocument saved=world.Capture();saved.actors[2].hunger=10;saved.actors[2].carriedFood=1;saved.actors[2].shelterId=183;saved.actors[2].shelterX=2;saved.actors[2].shelterY=5;saved.actors[2].shelterState=ShelterState.Inside;world=World.Restore(saved);Require(world.TryAssignHouse(2,2,5) && world.TryAssignDistributionCourier(2,183),"Could not bind second courier.");return world;
    }
    private static void CheckOrderFulfillmentCases()
