            World world=EncounterScenarios.CourierFulfillmentTest(),copy=Documents.ParseSave(State(world));bool claim=false,partial=false;
            for(int i=0;i<750 && world.CompletedSupplyOrders().Length==0;i++)
            {
                world.Step();copy.Step();Require(State(world)==State(copy),"Order fulfillment diverged after saving.");claim|=world.ActorAt(0).courierOrderId!=0;SupplyOrderDocument[] orders=world.PendingSupplyOrders();partial|=orders.Length>0 && orders[0].deliveredMeals==2;
                if(i%25==0)copy=Documents.ParseSave(State(world));Require(world.ActorAt(0).courierBoxes==null && world.ActorAt(0).assignedHouseId==183,"Automatic order rewrote manual route or home.");
            }
            Require(claim && partial && world.CompletedSupplyOrders().Length==1 && world.CompletedSupplyOrders()[0].deliveredMeals==4 && world.PendingSupplyOrders().Length==0,"Order did not progress from claim through partial to completed.");Require(world.FoodSupplies().RemainingMeals==32 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==26,"Shipment created food or removed an incorrect amount from center.");Require(State(Documents.ParseSave(State(world)))==State(world),"Completed order could not reload.");for(int i=0;i<70 && world.ShelfAt(12,7).food<4;i++)world.Step();Require(world.ShelfAt(12,7).food>=4,"Clerk failed to stock delivered food after returning from the phone.");
        });
        Check("Only one courier claims a phone order and expiry releases it for another courier",()=>{
            World world=TwoOrderCouriers();for(int i=0;i<60 && world.SupplyOrderCourier(1)==0;i++)world.Step();int owner=world.SupplyOrderCourier(1),index=owner==1?0:2,other=owner==1?3:1;Require(owner!=0 && (world.ActorAt(0).courierOrderId==0 || world.ActorAt(2).courierOrderId==0),"Two couriers claimed one order.");SaveDocument saved=world.Capture();saved.actors[index].restockUntilTick=saved.tick+1;world=World.Restore(saved);Run(world,4);Require(world.ActorAt(index).courierOrderId==0 && world.SupplyOrderCourier(1)==other && world.PendingSupplyOrders()[0].deliveredMeals==0,"Expired claim retained the order or lost progress.");
        });
