            World world=EncounterScenarios.CourierFulfillmentTest();world.TrySetStorageDonations(4,3,false);Run(world,40);Require(world.PendingSupplyOrders().Length==1 && world.SupplyOrderCourier(1)==0 && world.DistributionCenters()[0].StockMeals==30,"Dispatcher bypassed donation block.");world.TrySetStorageDonations(4,3,true);Require(world.TrySetCourierSchedule(0,19,12),"On-demand courier could not use a shift.");Run(world,10);Require(world.SupplyOrderCourier(1)==0,"Off-duty courier accepted order.");world.TrySetCourierSchedule(0,7,12);Run(world,5);Require(world.SupplyOrderCourier(1)==1,"On-duty courier did not accept order.");SaveDocument saved=EncounterScenarios.CourierFulfillmentTest().Capture();saved.map.storageBoxes[0].items[0].quantity=7;world=World.Restore(saved);Run(world,350);Require(world.DistributionCenters()[0].StockMeals==6 && world.PendingSupplyOrders().Length==1 && world.PendingSupplyOrders()[0].deliveredMeals==1 && world.CompletedSupplyOrders().Length==0,"Center reserve was consumed or partial shortage was marked complete.");
        });
        Check("Loaded couriers retain cargo if store configuration changes or the target becomes full",()=>{
            World world=EncounterScenarios.CourierFulfillmentTest();for(int i=0;i<70 && world.ActorAt(0).restockPhase!=RestockPhase.Returning;i++)world.Step();Require(world.ActorAt(0).carriedFood==3,"Could not reach loaded order trip.");SaveDocument loaded=world.Capture();int meals=world.FoodSupplies().RemainingMeals;Require(world.TryPlaceStorageBox(11,7) && world.TryConfigureStore(11,7),"Could not change store crate.");Require(world.ActorAt(0).courierOrderId==0 && world.ActorAt(0).carriedFood==3 && world.PendingSupplyOrders().Length==0 && world.FoodSupplies().RemainingMeals==meals && State(Documents.ParseSave(State(world)))==State(world),"Reconfiguration discarded cargo or left an unsavable claim.");world=World.Restore(loaded);world.TryUnassignClerk(1);SaveDocument full=world.Capture();Array.Find(full.map.storageBoxes,b=>b.x==13 && b.y==3).items=new[]{new ItemStackDocument{item=InventoryItem.Food,quantity=4}};world=World.Restore(full);Run(world,220);Require(world.PendingSupplyOrders()[0].deliveredMeals==0 && world.CompletedSupplyOrders().Length==0 && world.FoodSupplies().RemainingMeals==36,"Full destination deleted cargo, overfilled stock or credited a failed deposit.");
        });
        Check("The final small load is capped to remaining order quantity despite reserve-zero destination",()=>{
            SaveDocument saved=EncounterScenarios.CourierFulfillmentTest().Capture();StorageBoxDocument crate=Array.Find(saved.map.storageBoxes,b=>b.x==13 && b.y==3);crate.capacity=1;crate.foodReserve=0;World world=World.Restore(saved);for(int i=0;i<450 && world.CompletedSupplyOrders().Length==0;i++)world.Step();Require(world.CompletedSupplyOrders().Length==1 && world.CompletedSupplyOrders()[0].deliveredMeals==1 && world.DistributionCenters()[0].StockMeals==29 && world.FoodSupplies().RemainingMeals==32,"One-meal order over-collected, ignored explicit request or lost food.");
        });
        Check("Active orders finish their current load at shift end and preserve partial progress",()=>{
            SaveDocument saved=EncounterScenarios.CourierFulfillmentTest().Capture();saved.tick=7140;World world=World.Restore(saved);world.TrySetCourierSchedule(0,7,12);Run(world,500);Require(world.PendingSupplyOrders().Length==1 && world.PendingSupplyOrders()[0].deliveredMeals==2 && world.CompletedSupplyOrders().Length==0 && world.ActorAt(0).courierOrderId==0 && world.HouseAt(world.ActorAt(0).x,world.ActorAt(0).y)==183,"Shift end cancelled cargo, started another load or erased partial order progress.");world.TrySetCourierSchedule(0,19,12);for(int i=0;i<700 && world.CompletedSupplyOrders().Length==0;i++)world.Step();Require(world.CompletedSupplyOrders().Length==1 && world.CompletedSupplyOrders()[0].deliveredMeals==4,"Next work period did not finish partial order.");
        });
        Check("A clerk beside the entrance does not repeatedly shut out an order courier",()=>{
            SaveDocument saved=EncounterScenarios.CourierFulfillmentTest().Capture();saved.map.phoneBlocks[0].x=11;saved.map.phoneBlocks[0].y=6;World world=World.Restore(saved);for(int i=0;i<750 && world.CompletedSupplyOrders().Length==0;i++)world.Step();Require(world.CompletedSupplyOrders().Length==1 && world.CompletedSupplyOrders()[0].deliveredMeals==4,"Door-side clerk repeatedly closed the entrance before the courier could cross.");
        });
        Check("Completed order history and claim records reject malformed and legacy state",()=>{
            World world=EncounterScenarios.CourierFulfillmentTest();for(int i=0;i<750 && world.CompletedSupplyOrders().Length==0;i++)world.Step();Require(world.CompletedSupplyOrders().Length==1,"Missing completed validation order.");SupplyOrderDocument[] history=world.CompletedSupplyOrders();history[0].deliveredMeals=0;Require(world.CompletedSupplyOrders()[0].deliveredMeals==4,"Completed records escaped by reference.");Action<Action<SaveDocument>> bad=change=>{SaveDocument saved=world.Capture();change(saved);Reject(()=>World.Restore(saved));};bad(s=>s.rulesVersion=EncounterRules.SupplyRequestsVersion);bad(s=>s.completedSupplyOrders[0].deliveredMeals=0);bad(s=>s.completedSupplyOrders=new[]{s.completedSupplyOrders[0],s.completedSupplyOrders[0]});bad(s=>s.actors[0].courierOrderId=1);bad(s=>{s.completedSupplyOrders[0].requestedMeals=1001;s.completedSupplyOrders[0].deliveredMeals=1001;});SaveDocument legacy=EncounterScenarios.PhoneSupplyOrderTest().Capture();legacy.rulesVersion=EncounterRules.SupplyRequestsVersion;World old=World.Restore(legacy);Run(old,30);Require(!old.OrderFulfillmentEnabled && old.PendingSupplyOrders().Length==1 && old.CompletedSupplyOrders().Length==0,"Older phone-order rules gained automatic dispatch.");
        });
    }
